INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Regulagem Diária e Ajuste de Altura das Linhas de Nipple', '* **Diagnóstico Zootécnico:** Linhas de bebedouros posicionadas em altura incorreta causam graves prejuízos. Se estiverem baixas demais, as aves batem as asas e o dorso nos pinos ao se movimentarem, provocando gotejamento constante, umedecimento da cama e desperdício de milhares de litros de água tratada. Se estiverem altas demais, provocam restrição hídrica involuntária, desidratando o lote e derrubando o ganho de peso.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja para Produção de Ovos Caipiras - Atibaia' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Regulagem Diária e Ajuste de Altura das Linhas de Nipple' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Purgamento e Flushing Estruturado das Tubulações de Água', '* **Diagnóstico Zootécnico:** Ao longo do ciclo produtivo, a baixa velocidade da água e a passagem contínua de suplementos, vitaminas e vacinas geram um biofilme espesso nas paredes internas dos canos. Esse biofilme abriga colônias de bactérias patogênicas (*Salmonella* e *E. coli*) e trava as microesferas dos nipples, gerando entupimentos ou vazamentos contínuos.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Sítio com 2 Granjas - São Pedro' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Purgamento e Flushing Estruturado das Tubulações de Água' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Monitoramento Contínuo e Correção do pH da Água de Bebida', '* **Diagnóstico Zootécnico:** A água de poço com pH alcalino (acima de 7.5) inativa a ação germicida do cloro (o ácido hipocloroso livre se dissocia em íon hipoclorito, cuja eficácia germicida é 80 vezes menor). Por outro lado, pH ácido demais (abaixo de 5.5) corrói vedações de bebedouros, agride a mucosa digestiva e reduz a palatabilidade da água.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja Automatizada para 220 Mil Aves - Cerquilho' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Monitoramento Contínuo e Correção do pH da Água de Bebida' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Auditoria Diária de Hidrômetro e Teste de Estática Noturna', '* **Diagnóstico Zootécnico:** Rompimentos subterrâneos em conexões de PVC ou boias desreguladas em caixas elevadas podem desperdiçar de 5.000 a 20.000 litros de água por semana sem gerar poças visíveis na superfície. O hidrômetro é a principal ferramenta de diagnóstico financeiro do produtor.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja em Plena Produção - Cerquilho' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Auditoria Diária de Hidrômetro e Teste de Estática Noturna' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Gestão Térmica da Água de Bebida em Dias de Calor Extremo', '* **Diagnóstico Zootécnico:** O frango de corte é extremamente sensível à temperatura da água. Se a água na tubulação ultrapassar **25°C**, a ave reduz o consumo; se ultrapassar **30°C**, os frangos recusam a ingestão, sofrem estresse calórico severo, param de comer e podem morrer por asfixia térmica.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja Automatizada em Atividade - Itapira' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Gestão Térmica da Água de Bebida em Dias de Calor Extremo' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Teste Semanal do Gerador sob Carga Real e Manutenção Preventiva', '* **Diagnóstico Zootécnico:** Em granjas automatizadas (Dark House e pressão negativa), uma queda de energia elétrica por apenas 15 minutos em lotes adultos fecha a renovação de ar, eleva a temperatura acima de 40°C e causa morte em massa por asfixia. Testar o gerador "a vazio" (sem carga conectada) não garante que o motor suportará o pico de partida simultâneo dos exaustores.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja e Propriedade Rural de 6,16 Alqueires - Itapira' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Teste Semanal do Gerador sob Carga Real e Manutenção Preventiva' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Manutenção Preventiva de Exaustores: Tensão de Correias e Limpeza', '* **Diagnóstico Zootécnico:** Exaustores operando com venezianas empoeiradas ou correias frouxas perdem até 30% da sua capacidade volumétrica de sucção de ar (CFM), enquanto o motor elétrico continua puxando 100% da sua corrente elétrica nominal. Isso obriga o sistema a ligar mais exaustores do que o necessário.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Aves com 6 Alqueires - Amparo' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Manutenção Preventiva de Exaustores: Tensão de Correias e Limpeza' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Gestão de Consumo no Horário de Ponta e Tarifação Rural', '* **Diagnóstico Zootécnico:** As distribuidoras de energia cobram tarifas até 5 vezes mais caras pelo kWh consumido durante o Horário de Ponta (geralmente entre 18:00 e 21:00 em dias úteis). Utilizar a rede convencional nesse horário eleva drasticamente a fatura de luz do integrado.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Aviário 12 x 126 - Indaiatuba' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Gestão de Consumo no Horário de Ponta e Tarifação Rural' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Vedação Hermética do Aviário e Calibração da Pressão Estática', '* **Diagnóstico Zootécnico:** Frestas em portas, cortinas rasgadas e fendas no forro quebram o vácuo interno do galpão. O ar frio entra por locais errados caindo direto nas aves, e os exaustores precisam rodar o dobro do tempo para tentar gerar a renovação correta, gastando eletricidade sem alcançar a velocidade desejada.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Aves - Santo Antônio de Posse' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Vedação Hermética do Aviário e Calibração da Pressão Estática' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Manutenção e Limpeza Periódica de Painéis Solares Fotovoltaicos', '* **Diagnóstico Zootécnico:** Em fazendas avícolas, a dispersão contínua de poeira da maravalha, ração e penugem expelida pelos exaustores assenta sobre os módulos solares fotovoltaicos. Essa camada de sujeira cria um sombreamento artificial que reduz a geração de eletricidade em até 30%.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Arrendamento de Aviário - Ibiúna' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Manutenção e Limpeza Periódica de Painéis Solares Fotovoltaicos' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Controle Rigoroso da Umidade Relativa do Ar (50% a 70%)', '* **Diagnóstico Zootécnico:** Nos primeiros dias de vida das pintainhas, umidade relativa do ar (UR) abaixo de 50% causa desidratação severa das mucosas respiratórias e ressecamento das patas. Acima de 70%, o ar saturado impede a perda natural de calor das aves, empasta a maravalha e acelera a liberação de amônia.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Frango Automatizada - Bragança Paulista' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Controle Rigoroso da Umidade Relativa do Ar (50% a 70%)' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Cálculo da Ventilação Mínima Baseada na Biomassa Total do Lote', '* **Diagnóstico Zootécnico:** A ventilação mínima não tem como função resfriar as aves, mas sim renovar o oxigênio e remover o dióxido de carbono (CO₂), amônia (NH₃) e vapor d''água acumulados. Ventilar pouco intoxica o lote; ventilar em excesso esfria o ambiente e consome combustível de aquecimento sem necessidade.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja Poedeira - Itapetininga' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Cálculo da Ventilação Mínima Baseada na Biomassa Total do Lote' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Ajuste de Velocidade do Ar em Túnel de Vento nos Dias de Calor', '* **Diagnóstico Zootécnico:** Como as aves não transpiram, sua principal forma de perder calor com mais de 28 dias é pela sensação térmica provocada pela velocidade do ar passando sobre as penas (efeito *Wind Chill*). Vento insuficiente causa sufocamento e infarto térmico; vento excessivo em aves jovens provoca resfriamento indesejado.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Sítio com Aviário Antigo - Serra Negra' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Ajuste de Velocidade do Ar em Túnel de Vento nos Dias de Calor' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Manejo e Manutenção de Placas Evaporativas de Resfriamento', '* **Diagnóstico Zootécnico:** As placas de celulose evaporativa reduzem a temperatura do ar de entrada em até 6°C a 8°C. Se estiverem incrustadas por sais minerais ou algas, elas restringem a passagem de ar, elevando o vácuo a níveis perigosos e sobrecarregando os motores dos exaustores.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Aves - São Carlos' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Manejo e Manutenção de Placas Evaporativas de Resfriamento' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Monitoramento de Gases Críticos: Amônia (NH₃) e Dióxido de Carbono (CO₂)', '* **Diagnóstico Zootécnico:** Concentrações de amônia (NH₃) acima de 20 ppm destroem os cílios protetores da traqueia das aves, abrindo caminho para aerossaculite, bronquite e ceratoconjuntivite (cegueira). Níveis de dióxido de carbono (CO₂) acima de 3.000 ppm nos primeiros dias provocam ascite ("barriga d''água") e morte por insuficiência cardíaca.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Sítio Granja à Venda - Tatuí' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Monitoramento de Gases Críticos: Amônia (NH₃) e Dióxido de Carbono (CO₂)' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Pré-Aquecimento do Galpão e Temperatura do Piso a 32°C', '* **Diagnóstico Zootécnico:** O pintainho de um dia não controla sua própria temperatura corporal nos primeiros dias. Se a maravalha do piso estiver fria, a ave perde calor por condução direta pelo abdômen e pés, entrando em hipotermia, retendo o saco vitelino e sofrendo paralisia digestiva.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Compro Granja de Postura Caipira - São Paulo' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Pré-Aquecimento do Galpão e Temperatura do Piso a 32°C' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Avaliação do Enchimento de Papo às 8, 12 e 24 Horas', '* **Diagnóstico Zootécnico:** As primeiras 24 horas determinam o sucesso do lote. Se a ave não ingerir água e ração nesse período, o vitelo materno apodrece no abdômen, a mortalidade inicial dispara e o desenvolvimento intestinal fica irremediavelmente comprometido.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Sítio com Granjas de Frangos - Pereiras' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Avaliação do Enchimento de Papo às 8, 12 e 24 Horas' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Forração com Papel Kraft e Ração Pré-Inicial no Chão', '* **Diagnóstico Zootécnico:** Ao saírem das caixas do incubatório, as pintainhas se guiam pelo estímulo visual e sonoro de bicadas no chão. Colocar ração apenas nos comedouros tubulares automáticos resulta em baixa ingestão inicial e consumo acidental de maravalha da cama.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Sítio com Duas Granjas de Frango de Corte - Guatapará' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Forração com Papel Kraft e Ração Pré-Inicial no Chão' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Prevenção de Acúmulo de Ração e Controle de Micotoxinas', '* **Diagnóstico Zootécnico:** Ração empedrada nos cantos dos pratos em ambientes de alta umidade torna-se substrato propício para proliferação de fungos (*Aspergillus*, *Fusarium* e *Penicillium*). As micotoxinas produzidas lesam o fígado, causam hemorragias internas e suprimem gravemente o sistema imune da ave.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja Frango de Corte - São Paulo' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Prevenção de Acúmulo de Ração e Controle de Micotoxinas' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Regulagem de Altura dos Pratos conforme o Crescimento das Aves', '* **Diagnóstico Zootécnico:** Quando as linhas de comedouro permanecem baixas demais, os frangos ciscam com as patas e sacodem o pescoço lateralmente, atirando quilos de ração balanceada na maravalha, onde se perde para sempre. Se estiverem altas demais, as aves menores do lote não conseguem se alimentar.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Aves/Aviários — Registro Fictício - São Paulo' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Regulagem de Altura dos Pratos conforme o Crescimento das Aves' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Higienização e Tratamento Térmico dos Silos de Ração entre Lotes', '* **Diagnóstico Zootécnico:** Durante o calor do dia e o esfriamento da noite, a condensação de umidade nas chapas de aço galvanizado do silo faz com que a poeira de ração grude no cone de saída e nas paredes. Com o tempo, formam-se crostas pretas altamente tóxicas e cheias de fungos que contaminam cada nova entrega de ração.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja para Produção de Ovos Caipiras - Atibaia' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Higienização e Tratamento Térmico dos Silos de Ração entre Lotes' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Cascudamento Estruturado e Fermentação Anaeróbica da Cama', '* **Diagnóstico Zootécnico:** O cascudinho da cama (*Alphitobius diaperinus*) é o principal transmissor biológico de bactérias (*Salmonella*, *E. coli*) e vírus (Gumboro e Marek), além de roer as placas de isolamento térmico de poliuretano e isopor do aviário, destruindo a vedação e o conforto térmico.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Sítio com 2 Granjas - São Pedro' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Cascudamento Estruturado e Fermentação Anaeróbica da Cama' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Reviração Localizada da Cama e Prevenção de Calo de Pata', '* **Diagnóstico Zootécnico:** Pontos de cama úmida e compactada ("cascões") sob os bebedouros contêm altas concentrações de ácido úrico e umidade. O contato contínuo das patas das aves com essa pasta queima a pele, gerando pododermatite (calo de pata). No abatedouro, as patas de frango são produtos nobres de exportação; lotes com calo sofrem pesados descontos financeiros no acerto final.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja Automatizada para 220 Mil Aves - Cerquilho' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Reviração Localizada da Cama e Prevenção de Calo de Pata' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Operação Integral e Controle de Diluição do Arco de Desinfecção', '* **Diagnóstico Zootécnico:** Caminhões de ração, transporte de pintinhos, gás e retirada de aves visitam múltiplas propriedades rurais todos os dias. As rodas, pneus e chassis são os principais transportadores mecânicos de vírus altamente contagiosos (como Influenza Aviária e Newcastle) para o interior da granja.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja em Plena Produção - Cerquilho' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Operação Integral e Controle de Diluição do Arco de Desinfecção' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Manejo e Aplicação Correta de Vacinas via Água de Bebida', '* **Diagnóstico Zootécnico:** As vacinas vivas atenuadas (como Gumboro e Bronquite Infecciosa) são compostas por vírus frágeis. Se forem adicionadas a água tratada com cloro residual, metais pesados ou desinfetantes, as partículas virais morrem imediatamente nos canos, deixando o lote vulnerável a doenças fatais.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja Automatizada em Atividade - Itapira' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Manejo e Aplicação Correta de Vacinas via Água de Bebida' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Vazio Sanitário Rigoroso e Limpeza Terminal entre Lotes', '* **Diagnóstico Zootécnico:** Reduzir o tempo de vazio sanitário entre lotes para antecipar alojamentos impede a quebra do ciclo de vida de vírus, fungos e bactérias residuais. Patógenos do lote anterior contaminam os pintinhos recém-nascidos nos primeiros dias de vida, comprometendo todo o ciclo zootécnico.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja e Propriedade Rural de 6,16 Alqueires - Itapira' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Vazio Sanitário Rigoroso e Limpeza Terminal entre Lotes' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Padronização da Pesagem Semanal e Análise de Uniformidade', '* **Diagnóstico Zootécnico:** Pesar frangos em horários alternados ou capturar apenas aves próximas à porta gera amostragem viciada que distorce o cálculo da conversão alimentar e da curva de ganho de peso. Sem números reais de balança, o produtor não consegue antecipar a data ideal de abate nem detectar atrasos de crescimento.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Aves com 6 Alqueires - Amparo' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Padronização da Pesagem Semanal e Análise de Uniformidade' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Respeito Estrito à Densidade Zootécnica por Metro Quadrado', '* **Diagnóstico Zootécnico:** Ultrapassar a capacidade de lotação que a estrutura física e a exaustão do aviário suportam gera superlotação, eleva a temperatura corporal em grupo, provoca brigas por bebedouros e comedouros, e resulta em arranhões graves de carcaça provocados pelo pisoteio.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Aviário 12 x 126 - Indaiatuba' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Respeito Estrito à Densidade Zootécnica por Metro Quadrado' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Registro Diário da Curva de Mortalidade e Retirada Sanitária', '* **Diagnóstico Zootécnico:** Deixar aves mortas no chão do aviário atrai moscas, dissemina bactérias patogênicas para as aves vivas que bicam as carcaças e contamina a cama com fluidos em decomposição. Não registrar as baixas no sistema mascara o consumo real de água e ração por ave viva.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Aves - Santo Antônio de Posse' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Registro Diário da Curva de Mortalidade e Retirada Sanitária' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Cumprimento do Programa de Escuro e Fotoperíodo Noturno', '* **Diagnóstico Zootécnico:** Manter lâmpadas acesas 24 horas por dia gera estresse crônico, canibalismo e exaustão física. O frango de corte necessita de períodos de escuro para secretar melatonina, que fortalece o sistema imunológico, consolida o desenvolvimento ósseo das pernas e reduz mortes por infarto (morte súbita) e ascite em lotes de alto crescimento.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Arrendamento de Aviário - Ibiúna' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Cumprimento do Programa de Escuro e Fotoperíodo Noturno' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Manejo Cuidadoso de Pós-Apanha e Preparação do Carregamento', '* **Diagnóstico Zootécnico:** O momento do carregamento das aves para o abatedouro é a etapa com maior incidência de hematomas nas asas e coxas, fraturas ósseas e mortes por asfixia causadas por apanha violenta ou falta de jejum alimentar adequado. Qualquer hematoma grave gera condenação da peça no frigorífico, descontando o peso útil pago ao integrado.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja de Frango Automatizada - Bragança Paulista' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Manejo Cuidadoso de Pós-Apanha e Preparação do Carregamento' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
INSERT INTO tips (title, tip, image_url, foto_url) VALUES ('Calibração de Sensores e Redundância de Termostatos de Emergência', '* **Diagnóstico Zootécnico:** Sensores ambientais de temperatura e umidade com crostas de poeira ou descalibrados enviam dados falsos com erro de até 3°C a 4°C para o computador climático. Isso pode fazer com que o sistema ligue exaustores sem necessidade no frio (gastando luz e congelando as aves) ou deixe de climatizar no calor extremo.
INSERT INTO farms_tips (id_farm, id_tip) VALUES ((SELECT id FROM farms WHERE name = 'Granja Poedeira - Itapetininga' ORDER BY id DESC LIMIT 1), (SELECT id FROM tips WHERE title = 'Calibração de Sensores e Redundância de Termostatos de Emergência' ORDER BY id DESC LIMIT 1)) ON CONFLICT (id_farm, id_tip) DO NOTHING;
